def test_collect_uses_epoch_fallbacks_for_unsupported_epoch_formats(monkeypatch):
    epoch_ts = 1704164645.75
    epoch_format_values = iter(("%", "epoch-int-input"))

    now_values = {
        "%Y": "2024",
        "%m": "01",
        "%A": "Tuesday",
        "%w": "2",
        "%W": "01",
        "%d": "02",
        "%H": "03",
        "%M": "04",
        "%S": "05",
        "%Y-%m-%d": "2024-01-02",
        "%H:%M:%S": "03:04:05",
        "%Y%m%dT%H%M%S%f": "20240102T030405123456",
        "%Y%m%dT%H%M%S": "20240102T030405",
    }
    utc_values = {
        "%Y-%m-%dT%H:%M:%S.%fZ": "2024-01-02T03:04:05.123456Z",
        "%Y-%m-%dT%H:%M:%SZ": "2024-01-02T03:04:05Z",
    }

    class PercentInt:
        def __str__(self):
            return "%unsupported"

    class FakeDateTime:
        def __init__(self, values):
            self.values = values

        def strftime(self, fmt):
            if fmt == "%s":
                return next(epoch_format_values)
            return self.values[fmt]

    class FakeDateTimeClass:
        @staticmethod
        def fromtimestamp(value):
            assert value == epoch_ts
            return FakeDateTime(now_values)

        @staticmethod
        def utcfromtimestamp(value):
            assert value == epoch_ts
            return FakeDateTime(utc_values)

    def fake_int(value):
        if value == epoch_ts:
            return 1704164645
        if value == "epoch-int-input":
            return PercentInt()
        raise AssertionError("unexpected int() argument: {!r}".format(value))

    fake_time = types.SimpleNamespace(
        time=lambda: epoch_ts,
        strftime=lambda fmt: {"%Z": "TEST", "%z": "+0000"}[fmt],
        tzname=("STANDARD", "DAYLIGHT"),
    )

    monkeypatch.setattr(
        date_time,
        "datetime",
        types.SimpleNamespace(datetime=FakeDateTimeClass),
    )
    monkeypatch.setattr(date_time, "time", fake_time)
    monkeypatch.setattr(date_time, "int", fake_int, raising=False)

    result = date_time.DateTimeFactCollector().collect()

    assert result["date_time"]["epoch"] == "1704164645"
    assert result["date_time"]["epoch_int"] == "1704164645"
    assert result["date_time"]["date"] == "2024-01-02"
    assert result["date_time"]["iso8601"] == "2024-01-02T03:04:05Z"
    assert result["date_time"]["tz_dst"] == "DAYLIGHT"
